package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.MapperConfig;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for CreatorCollector.verifyNonDup
 */
public class CreatorCollector_verifyNonDup_TriageGen2Test {

    private CreatorCollector creatorCollector;
    private BeanDescription beanDesc;
    private MapperConfig<?> config;

    // Accessor for the protected method using reflection since it's protected
    private Method verifyNonDupMethod;

    @Before
    public void setUp() throws Exception {
        beanDesc = mock(BeanDescription.class);
        config = mock(MapperConfig.class);
        creatorCollector = new CreatorCollector(beanDesc, config);
        verifyNonDupMethod = CreatorCollector.class.getDeclaredMethod("verifyNonDup", 
                AnnotatedWithParams.class, int.class, boolean.class);
        verifyNonDupMethod.setAccessible(true);
    }

    private void invokeVerifyNonDup(AnnotatedWithParams newOne, int typeIndex, boolean explicit) throws Exception {
        verifyNonDupMethod.invoke(creatorCollector, newOne, typeIndex, explicit);
    }

    /**
     * Helper to mock AnnotatedWithParams and its behavior
     */
    private AnnotatedWithParams mockAnnotated(Class<?> type) {
        AnnotatedWithParams anno = mock(AnnotatedWithParams.class);
        when(anno.getRawParameterType(0)).thenReturn(type);
        return anno;
    }

    @Test
    public void testFirstTimeAddition() throws Exception {
        AnnotatedWithParams newOne = mockAnnotated(String.class);

        // Initial state: _creators[0] is null
        invokeVerifyNonDup(newOne, 0, false);

        assertTrue(creatorCollector.hasDefaultCreator());
        // We can't easily access _creators directly without reflection, 
        // but we can verify through side effects if necessary. 
        // For this test, we ensure no exception is thrown and internal flag is set.
    }

    @Test
    public void testExplicitAdditionFirstTime() throws Exception {
        AnnotatedWithParams newOne = mockAnnotated(String.class);
        invokeVerifyNonDup(newOne, 0, true);
        assertTrue(creatorCollector.hasDefaultCreator());
    }

    @Test
    public void testSkipIfAlreadyExplicitAndNewIsNotExplicit() throws Exception {
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(Integer.class);

        // 1. Set the first one as explicit
        invokeVerifyNonDup(oldOne, 0, true);

        // 2. Try to add a non-explicit one. Should return early without changing oldOne or throwing error.
        invokeVerifyNonDup(newOne, 0, false);

        // Since we can't check _creators directly, we check if it threw exception.
        // If it didn't return early, it might have hit the class comparison logic.
    }

    @Test
    public void testBothExplicitTriggersVerification() throws Exception {
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(String.class);

        invokeVerifyNonDup(oldOne, 0, true);

        // Both explicit and same class and same type -> Should throw IllegalArgumentException
        try {
            invokeVerifyNonDup(newOne, 0, true);
            fail("Expected IllegalArgumentException");
        } catch (Exception e) {
            // Reflection wraps the actual exception in InvocationTargetException
            assertTrue(e.getCause() instanceof IllegalArgumentException);
            assertTrue(e.getCause().getMessage().contains("Conflicting"));
        }
    }

    @Test
    public void testVerifyWhenOnlyOneIsExplicit() throws Exception {
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(String.class);

        // Add old one as non-explicit
        invokeVerifyNonDup(oldOne, 0, false);

        // Add new one as explicit. 
        // Logic: (oldOne != null) AND (_explicitCreators & mask == 0) AND (!explicit is false) -> verify = true
        // Since types are same, it should throw.
        try {
            invokeVerifyNonDup(newOne, 0, true);
            fail("Expected IllegalArgumentException");
        } catch (Exception e) {
            assertTrue(e.getCause() instanceof IllegalArgumentException);
        }
    }

    @Test
    public void testVerifyWhenNeitherIsExplicit() throws Exception {
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(String.class);

        invokeVerifyNonDup(oldOne, 0, false);

        // Logic: verify = !explicit -> !false = true
        try {
            invokeVerifyNonDup(newOne, 0, false);
            fail("Expected IllegalArgumentException");
        } catch (Exception e) {
            assertTrue(e.getCause() instanceof IllegalArgumentException);
        }
    }

    @Test
    public void testNewTypeMoreGenericUsesOld() throws Exception {
        // oldType = String.class, newType = Object.class
        // Object.class.isAssignableFrom(String.class) is true (new is more generic/parent)
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(Object.class);

        invokeVerifyNonDup(oldOne, 0, false);

        // Should return early without throwing and without updating _creators to newOne
        invokeVerifyNonDup(newOne, 0, false);
    }

    @Test
    public void testNewTypeMoreSpecificUsesNew() throws Exception {
        // oldType = Object.class, newType = String.class
        // String.class.isAssignableFrom(Object.class) is true
        // But logic check: if (newType.isAssignableFrom(oldType)) return;
        // If newType is String and oldType is Object: String.isAssignableFrom(Object) is true.
        // Wait, the code says: if (newType.isAssignableFrom(oldType)) return; (meaning new is more generic)
        // Let's re-read: if newType is String and oldType is Object -> String.isAssignableFrom(Object) is true -> return.
        // Actually, if new is String (specific) and old is Object (generic), newType.isAssignableFrom(oldType) is true.
        // The comment says "new type more generic, use old". 
        // In Java: String.class.isAssignableFrom(Object.class) is FALSE.
        // Object.class.isAssignableFrom(String.class) is TRUE.

        // Case 1: newType = Object (generic), oldType = String (specific). 
        // Object.isAssignableFrom(String) -> true. Returns (uses old).
        AnnotatedWithParams oldOne = mockAnnotated(String.class);
        AnnotatedWithParams newOne = mockAnnotated(Object.class);
        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(newOne, 0, false); // Should return

        // Case 2: newType = String (specific), oldType = Object (generic).
        // String.isAssignableFrom(Object) -> false. 
        // Should proceed to update _creators[typeIndex] = newOne.
        AnnotatedWithParams oldOne2 = mockAnnotated(Object.class);
        AnnotatedWithParams newOne2 = mockAnnotated(String.class);
        invokeVerifyNonDup(oldOne2, 0, false);
        invokeVerifyNonDup(newOne2, 0, false); // Should update
    }

    @Test
    public void testDifferentClassesDoNotVerify() throws Exception {
        // Even if types match, if the AnnotatedWithParams implementation class is different, it skips verify
        AnnotatedWithParams oldOne = mock(AnnotatedWithParams.class);
        AnnotatedWithParams newOne = mock(AnnotatedWithParams.class);

        when(oldOne.getRawParameterType(0)).thenReturn(String.class);
        when(newOne.getRawParameterType(0)).thenReturn(String.class);
        // Ensure oldOne.getClass() != newOne.getClass()

        invokeVerifyNonDup(oldOne, 0, false);
        invokeVerifyNonDup(newOne, 0, false); // Should not throw
    }
}
